DEFAULTS = {"retries": 3, "timeout": 5.0}

def handle(request, config=DEFAULTS):
    if "timeout" in request:
        config["timeout"] = request["timeout"]   # mutates the module-level dict
    return config["timeout"]

print(handle({"timeout": 0.5}))
print(handle({}))            # a different request, same dict
print(DEFAULTS)
